def transform(grid):
    H, W = len(grid), len(grid[0])
    bg = grid[0][0]
    cr, cc, c_color = -1, -1, 0

    # Find cross row
    for r in range(H):
        if all(grid[r][c] == grid[r][0] for c in range(W)) and grid[r][0] != bg:
            cr, c_color = r, grid[r][0]
            break

    # Find cross col
    for c in range(W):
        if all(grid[r][c] == grid[0][c] for r in range(H)) and grid[0][c] != bg:
            cc = c
            break

    if cr == -1 or cc == -1:
        return grid

    # Find pattern quadrant
    quadrants = [
        (0, cr, 0, cc),       # TL
        (0, cr, cc + 1, W),   # TR
        (cr + 1, H, 0, cc),   # BL
        (cr + 1, H, cc + 1, W) # BR
    ]

    p_mat, h_sub, w_sub = None, 0, 0

    for rmin, rmax, cmin, cmax in quadrants:
        for r in range(rmin, rmax):
            found = False
            for c in range(cmin, cmax):
                if grid[r][c] != bg and grid[r][c] != c_color:
                    # Found pattern, extract this quadrant
                    p_mat = []
                    for r in range(rmin, rmax):
                        row_d = []
                        for c in range(cmin, cmax):
                            v = grid[r][c]
                            if v != bg and v != c_color:
                                row_d.append(c_color)
                            else:
                                row_d.append(bg)
                        p_mat.append(row_d)
                    h_sub = rmax - rmin
                    w_sub = cmax - cmin
                    found = True
                    break
            if found:
                break
        if p_mat:
            break

    if p_mat:
        out = [[bg] * (W - 1) for _ in range(H - 1)]
        h_top = cr
        h_bot = H - 1 - cr
        w_left = cc
        w_right = W - 1 - cc

        for r in range(h_sub):
            for c in range(w_sub):
                val = p_mat[r][c]
                # TL
                if r < h_top and c < w_left:
                    out[r][c] = val
                # TR
                if r < h_top and c < w_right:
                    out[r][w_left + c] = val
                # BL
                if r < h_bot and c < w_left:
                    out[h_top + r][c] = val
                # BR
                if r < h_bot and c < w_right:
                    out[h_top + r][w_left + c] = val

        return out

    return grid
